import{_ as e,o as r,c as l,ag as t}from"./chunks/framework.DXGyWiRo.js";const u=JSON.parse('{"title":"行为准则","description":"","frontmatter":{},"headers":[],"relativePath":"CODE_OF_CONDUCT.md","filePath":"CODE_OF_CONDUCT.md","lastUpdated":1776785343000}'),i={name:"CODE_OF_CONDUCT.md"};function o(n,a,h,c,d,p){return r(),l("div",null,[...a[0]||(a[0]=[t('<h1 id="行为准则" tabindex="-1">行为准则 <a class="header-anchor" href="#行为准则" aria-label="Permalink to &quot;行为准则&quot;">​</a></h1><h2 id="🤝-我们的承诺" tabindex="-1">🤝 我们的承诺 <a class="header-anchor" href="#🤝-我们的承诺" aria-label="Permalink to &quot;🤝 我们的承诺&quot;">​</a></h2><p>为了营造开放和友好的环境，我们承诺让参与本项目和使用我们插件的每个人都感到受欢迎和安全，无论其年龄、体型、残疾、种族、性别特征、性别认同和表达、经验水平、教育程度、社会经济地位、国籍、个人外貌、种族、宗教或性认同和取向如何。</p><h2 id="📋-我们的标准" tabindex="-1">📋 我们的标准 <a class="header-anchor" href="#📋-我们的标准" aria-label="Permalink to &quot;📋 我们的标准&quot;">​</a></h2><p>积极行为示例包括：</p><ul><li>使用友好和包容的语言</li><li>尊重不同的观点和经验</li><li>优雅地接受建设性的批评</li><li>关注对社区最有利的事情</li><li>对其他社区成员表示同理心</li></ul><p>不可接受的行为包括：</p><ul><li>使用性别化语言或图像，以及不受欢迎的性关注或挑逗</li><li>恶意评论、侮辱/贬损评论，以及个人或政治攻击</li><li>公开或私下骚扰</li><li>未经明确许可发布他人的私人信息，如物理地址或电子邮件地址</li><li>其他被专业社区环境认为不适当的行为</li></ul><h2 id="🎯-我们的责任" tabindex="-1">🎯 我们的责任 <a class="header-anchor" href="#🎯-我们的责任" aria-label="Permalink to &quot;🎯 我们的责任&quot;">​</a></h2><p>项目维护者负责阐明可接受行为的标准，并对任何不可接受的行为采取适当和公平的纠正措施。</p><p>项目维护者有权并有权删除、编辑或拒绝与行为准则不符的评论、提交、代码、wiki 编辑、问题和其他贡献，并可暂时或永久禁止任何他们认为行为不当、威胁、冒犯或有害的贡献者。</p><h2 id="📧-适用范围" tabindex="-1">📧 适用范围 <a class="header-anchor" href="#📧-适用范围" aria-label="Permalink to &quot;📧 适用范围&quot;">​</a></h2><p>本行为准则适用于所有项目空间，并且当个人代表项目或其社区时也适用于公共空间。代表项目或社区的示例包括使用官方项目电子邮件地址、通过官方社交媒体帐户发布或在在线或离线活动中担任指定代表。项目维护者可以进一步阐明和澄清项目代表性。</p><h2 id="🔒-执行" tabindex="-1">🔒 执行 <a class="header-anchor" href="#🔒-执行" aria-label="Permalink to &quot;🔒 执行&quot;">​</a></h2><p>可以通过邮件联系项目团队以报告滥用行为：conduct@example.com</p><p>所有投诉都将被审查和调查，并将产生被认为必要且适合情况的回应。项目团队有义务对事件报告者保密。具体执行政策的更多细节可能会单独发布。</p><p>不善意遵守或执行行为准则的项目维护者可能面临项目领导层确定的其他临时或永久后果。</p><h2 id="📚-参考资料" tabindex="-1">📚 参考资料 <a class="header-anchor" href="#📚-参考资料" aria-label="Permalink to &quot;📚 参考资料&quot;">​</a></h2><ul><li><a href="https://www.contributor-covenant.org/" target="_blank" rel="noreferrer">贡献者公约</a></li><li><a href="https://www.contributor-covenant.org/faq" target="_blank" rel="noreferrer">行为准则 FAQ</a></li></ul><h2 id="🌟-联系方式" tabindex="-1">🌟 联系方式 <a class="header-anchor" href="#🌟-联系方式" aria-label="Permalink to &quot;🌟 联系方式&quot;">​</a></h2><p>如有任何问题或建议，请联系：conduct@example.com</p><hr><p>让我们共同维护一个友好、包容的社区！💖</p>',23)])])}const _=e(i,[["render",o]]);export{u as __pageData,_ as default};
